std::string OrcaPrinterBackend::change_printer(const ChangePrinterRequest& request, SavedPrinter& changed,
                                               std::vector<std::string>& discarded)
{
    std::vector<SavedPrinter> printers = saved_printers();
    const auto                found    = std::find_if(printers.begin(), printers.end(),
                                                      [&request](const SavedPrinter& saved) { return saved.name == request.name; });
    if (found == printers.end())
        return "This app no longer has a printer called \"" + request.name + "\".";

    if (request.nozzle) {
        const PrinterCandidate* variant = nullptr;
        for (const PrinterCandidate& candidate : m_catalog.candidates())
            if (candidate.model_id == found->model_id && nozzle_of(candidate.variant) == *request.nozzle)
                variant = &candidate;
        if (variant == nullptr)
            return found->model.empty() ? std::string("This printer does not come with that nozzle size.") :
                                          "The " + found->model + " does not come with that nozzle size.";
        const wxString problem = Printers::change_named_printer_nozzle(m_plater, request.name, variant->preset_name, discarded);
        if (!problem.empty())
            return problem.ToStdString();
    }

    for (const SavedPrinter& saved : saved_printers())
        if (saved.name == request.name)
            changed = saved;

    // The pane lists the project being prepared; Preview draws its own plate
    // picker and Home has no project in front.
    const bool left_pane_available = !home && m_tabpanel->GetSelection() == MainFrame::tp3DEditor;
    if (m_status_row != nullptr)
        m_status_row->set_left_pane_available(left_pane_available);
    const bool show_left_pane = left_pane_available && !m_left_pane_collapsed;
    m_left_pane->Show(show_left_pane);
    m_left_resize_handle->Show(show_left_pane);
    m_frame->Layout();
    apply_left_pane_width();
    set_agent_pane_collapsed(home ? true : m_agent_pane_user_collapsed);
}

void attach_shell(MainFrame& frame, Notebook* tabpanel, wxSizer* main_sizer)
{
    if (tabpanel == nullptr || main_sizer == nullptr)
        return;
    if (!wxGetApp().is_editor())
        return;
    if (wxGetApp().app_config != nullptr && wxGetApp().app_config->get("jusprin_shell") == "0")
        return;

    auto controller = std::make_unique<ShellController>();
    try {
        controller->install(frame, *tabpanel, *main_sizer);
    } catch (const std::exception& error) {
        BOOST_LOG_TRIVIAL(error) << "JusPrin shell could not be installed, keeping the standard "
                                    "presentation: " << error.what();
        return;
    }
    shell_slot() = std::move(controller);
}

